import json
path = '/private/tmp/claude-501/-Users-rina--claude/bcb2f2c2-3bd5-40de-a21c-025da566713f/scratchpad/batches/batch_0008.json'
with open(path, encoding='utf-8') as f:
    data = json.load(f)

def fix(s):
    if not s:
        return s
    try:
        return s.encode('latin1').decode('utf-8')
    except UnicodeDecodeError:
        try:
            return s.encode('latin1').decode('utf-8', errors='ignore')
        except Exception:
            return s
    except UnicodeEncodeError:
        return s

out = []
for item in data:
    new = dict(item)
    for k in ('title','desc','body'):
        if k in new and new[k]:
            new[k] = fix(new[k])
    out.append(new)

outpath = '/private/tmp/claude-501/-Users-rina--claude/bcb2f2c2-3bd5-40de-a21c-025da566713f/scratchpad/batch_0008_fixed.json'
with open(outpath, 'w', encoding='utf-8') as f:
    json.dump(out, f, ensure_ascii=False, indent=1)
print('done', len(out))
